-- Public project seed from server 23, exported 2026-10-23.
-- 200 projects; 13 followed. Metadata timestamps are original observations.
-- Excludes credentials, notes, ratings, README bodies, events and test results.
BEGIN;
SET LOCAL standard_conforming_strings = on;
SELECT pg_advisory_xact_lock(719436522);
CREATE TEMP TABLE watch_seed (
    id bigint PRIMARY KEY, full_name text NOT NULL, details jsonb NOT NULL,
    manual boolean NOT NULL, followed boolean NOT NULL, fetched_at timestamptz NOT NULL
) ON COMMIT DROP;
DO $$
BEGIN
    IF (SELECT count(*) FROM watch_projects WHERE NOT hidden) +
       (SELECT count(*) FROM watch_seed s WHERE NOT EXISTS (
           SELECT 1 FROM watch_projects p WHERE p.id = s.id)) > 200 THEN
        RAISE EXCEPTION 'Import would exceed 200 active projects; no data imported';
    END IF;
END $$;
    id, full_name, details, discovered_by, manual, followed, hidden,
    review_status, rating, notes, fetched_at, last_error
)
SELECT id, full_name, details, '["seed:server23"]'::jsonb, manual, followed, false,
       'pending', NULL, '', fetched_at, NULL
FROM watch_seed
ON CONFLICT (id) DO NOTHING;
COMMIT;
